      if(t>0){
        for(let l=1;l<=i;l++){
          const sum=S[i]-S[l-1];
          const val=dp[l-1][t-1]+sum*(i-l+1);
          if(val>dp[i][t]){ dp[i][t]=val; prv[i][t]=l; }
        }
      }
    }
  }
  // reconstruction omitted for brevity
  return {best:dp[n][k]};
}
